  async function detail(id){const r=invoice(id);if(!r)return;detailId=r.id;const supplier=data.suppliers.find(s=>s.id===r.supplier_id);modal(`${r.supplier_name} · ${data.types[r.document_type]} ${r.folio}`,'Factura, documentos, pagos y seguimiento',`${badge(r)}${r.payment_hold?`<p class="ap-notice">Pausa: ${e(r.payment_hold.reason)} · ${e(r.payment_hold.actor)}. Se excluye de programación y listados de pago.</p>`:''}<div class="ap-stats ap-detail-stats"><article><span>Total factura</span><strong>${money(r.amount)}</strong></article><article><span>Pagado</span><strong>${r.payment_review?'Por validar':money(r.paid)}</strong></article><article><span>Saldo</span><strong>${r.payment_review?'Por validar':money(r.balance)}</strong></article></div>${r.payment_review?`<p class="ap-notice">Importada del registro de compras. Confirma los pagos anteriores antes de incluirla en el listado de pagos.</p>`:''}<div class="ap-card"><p>Emisión: ${e(r.issued_on)} · Vencimiento: ${e(r.due_on||'por confirmar')}</p><p>${e(data.conditions[r.condition])} · ${e(r.description)}</p>${r.source?hint(`Origen: archivo SII · fila ${r.source.source_row}. El CSV no reemplaza la factura original.`):''}<p>Banco: ${e(supplier.bank||'por completar')} · Cuenta: ${e(supplier.account_number||'por completar')}</p></div><div class="ap-actions">${!r.voided_at?button('Editar factura','edit-invoice',r.id):''}${!r.voided_at&&r.payment_review?button('Validar saldo','reconcile',r.id,'primary'):r.balance&&!r.voided_at?button('Registrar pago / abono','payment',r.id,'primary'):''}${!r.voided_at&&!r.paid&&!hasActiveCredit(r)?button('Anular factura','void-invoice',r.id):''}${!r.voided_at&&(r.balance||r.payment_hold)?`<button type="button" class="button secondary" data-pp="hold" data-id="${r.id}">${r.payment_hold?'Resolver pausa de pago':'Pausar pago / disputa'}</button>`:''}</div>${r.scheduled_on?`<p class="hint">Programado para ${e(r.scheduled_on)}: ${money(r.planned_amount)}. Este importe todavía no está registrado como pagado.</p>`:''}<h3>Factura original y adjuntos</h3>${fileLinks(r.files.filter(f=>!f.payment_id))||hint('Sin original adjunto.')}${button('Adjuntar PDF o foto','attach-invoice',r.id)}<h3>Aplicaciones de cuenta corriente</h3><p>Pagos aplicados: ${money((r.applications||[]).filter(a=>a.kind==='payment'&&!a.voided_at&&!a.entry_voided_at).reduce((sum,a)=>sum+a.amount,0))} · Notas de crédito aplicadas: ${money(r.credited||0)}</p><button type="button" class="button secondary" data-ac="open" data-id="${r.supplier_id}">Ver cuenta corriente</button>${sharedPaymentProofs(r)}<h3>Pagos históricos y comprobantes</h3>${r.payments.map(p=>paymentCard(p,r)).join('')||hint('Sin pagos históricos en esta factura.')}<details class="ap-card"><summary>Historial de cambios</summary><div id="ap-history">Cargando…</div></details>`,'','PROVEEDORES Y PAGOS');const token=epoch;try{const result=await api(`/api/suppliers/invoices/${r.id}/history`);if(token!==epoch||detailId!==r.id||!$('#ap-history'))return;$('#ap-history').innerHTML=result.events.map(ev=>`<p><strong>${e(actions[ev.action]||ev.action)}</strong><br>${e(ev.actor)} · ${e(new Date(ev.created_at).toLocaleString('es-CL',{timeZone:'America/Santiago'}))}<br>${e(ev.reason)}<details><summary>Detalle</summary><pre>${e(JSON.stringify({antes:JSON.parse(ev.before_json),despues:JSON.parse(ev.after_json)},null,2))}</pre></details></p>`).join('');}catch(err){if($('#ap-history'))$('#ap-history').textContent=err.message;}}
  function statement(id){window.OvejaSupplierAccount.open(Number(id)).catch(err=>toast(err.message));}
