  function voidForm(kind,id){const r=kind==='void-payment'?data.invoices.find(v=>v.payments.some(p=>p.id===Number(id))):invoice(id);formModal(kind==='void-payment'?'Anular registro de pago':'Anular factura','El original y el historial se conservan.',input('Motivo de la anulación','reason','','required maxlength="500"')+hint(kind==='void-payment'?'El monto volverá al saldo pendiente. Esto no revierte una transferencia bancaria.':'La factura dejará de sumar deuda.'),kind,{...r,targetId:Number(id)});}
